String _qrPdfFilename(String prefix, String identifier) {
  final normalized = identifier
      .trim()
      .replaceAll(RegExp(r'[^A-Za-z0-9_-]+'), '-')
      .replaceAll(RegExp(r'-+'), '-')
      .replaceAll(RegExp(r'^-+|-+$'), '');
  return '${normalized.isEmpty ? prefix : '$prefix-$normalized'}.pdf';
}
